394	        Project project = projects.findById(projectId)
395	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown project"));
396	        LocalDate issued = request.issuedDate() != null ? request.issuedDate() : LocalDate.now();
397	        LocalDate due = request.dueDate() != null ? request.dueDate() : issued.plusDays(InvoiceRequest.DEFAULT_TERM_DAYS);
398	        if (due.isBefore(issued)) {
